-- =====================================================================
--  GÉNÉRATEUR D'EMPLOIS DU TEMPS : 02_import_donnees.sql
--  1) charge la base plate (AvancementProgramme2026, 592 lignes) dans une table de passage ;
--  2) normalise ces données dans les tables du modèle ;
--  3) affiche des contrôles.
--  À exécuter APRÈS 01_schema.sql. Peut être relancé : il vide d'abord les données importées.
-- =====================================================================
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
USE emplois_du_temps;

-- ---------- 0. Remise à zéro des données importées ----------
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM seance_professeur; DELETE FROM seance_groupe; DELETE FROM seance; DELETE FROM passage;
DELETE FROM unite_professeur; DELETE FROM volume_horaire; DELETE FROM unite_groupe; DELETE FROM unite_enseignement;
DELETE FROM module_type_salle; DELETE FROM professeur_module; DELETE FROM professeur;
DELETE FROM module; DELETE FROM groupe; DELETE FROM filiere; DELETE FROM secteur;
DELETE FROM semaine; DELETE FROM semestre; DELETE FROM annee_scolaire;
SET FOREIGN_KEY_CHECKS = 1;
DROP TABLE IF EXISTS stg_avancement;

-- ---------- 1. Table de passage (les 51 colonnes du fichier, dans le même ordre) ----------
CREATE TABLE stg_avancement (
  ligne INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  date_maj VARCHAR(30), annee SMALLINT, niveau VARCHAR(10), secteur VARCHAR(100), code_filiere VARCHAR(30),
  filiere VARCHAR(120), type_formation VARCHAR(40), creneau VARCHAR(10), groupe VARCHAR(20), effectif_groupe SMALLINT,
  sous_groupe VARCHAR(20), statut_sous_groupe VARCHAR(20), fusion_groupe VARCHAR(100), code_fusion VARCHAR(20),
  annee_formation TINYINT, mode_formation VARCHAR(30), code_module VARCHAR(20), module VARCHAR(200), regional CHAR(1),
  mle_present VARCHAR(20), formateur_present VARCHAR(120), mle_syn VARCHAR(20), formateur_syn VARCHAR(120),
  mhp_s1 DECIMAL(6,1), mhsyn_s1 DECIMAL(6,1), mhasyn_s1 DECIMAL(6,1), mh_total_s1 DECIMAL(6,1),
  mhp_s2 DECIMAL(6,1), mhsyn_s2 DECIMAL(6,1), mhasyn_s2 DECIMAL(6,1), mh_total_s2 DECIMAL(6,1),
  mhp_total DECIMAL(6,1), mhsyn_total DECIMAL(6,1), mhasyn_total DECIMAL(6,1), mh_total DECIMAL(6,1),
  mh_aff_present DECIMAL(6,1), mh_aff_sync DECIMAL(6,1), mh_aff_globale DECIMAL(6,1),
  mh_real_present DECIMAL(6,1), mh_real_sync DECIMAL(6,1), mh_real_globale DECIMAL(6,1),
  taux_real_present DECIMAL(6,2), taux_real_syn DECIMAL(6,2), taux_real_globale DECIMAL(6,2),
  moy_absence DECIMAL(4,1), nb_cc TINYINT, seance_efm VARCHAR(10), validation_efm VARCHAR(10),
  classe_teams VARCHAR(50), module_pie VARCHAR(50), efp_pie VARCHAR(50),
  cle_unite VARCHAR(120) NULL COMMENT 'Calculée après le chargement'
) ENGINE=InnoDB;


-- ---------- 2. Chargement des 592 lignes ----------

-- ---------- 3. Clé de rapprochement des unités d'enseignement ----------
-- Fusion réelle : le Code Fusion (avec la filière et le module). Sans fusion (code 0) : une unité par groupe et par module.
UPDATE stg_avancement
SET cle_unite = IF(code_fusion <> '0',
                   CONCAT(code_fusion, '|', code_filiere, '|', code_module),
                   CONCAT('SOLO|', groupe, '|', code_filiere, '|', code_module));

-- ---------- 4. Normalisation ----------
-- 4.1 Année scolaire et semestres (les dates sont à renseigner par l'administrateur)
SELECT DISTINCT annee, CONCAT(annee, '-', annee + 1) FROM stg_avancement;

SELECT a.id, n.numero FROM annee_scolaire a
CROSS JOIN (SELECT 1 AS numero UNION ALL SELECT 2) n;

-- 4.2 Secteurs et filières
SELECT DISTINCT TRIM(secteur) FROM stg_avancement;

SELECT s.code_filiere, TRIM(MAX(s.filiere)), MAX(se.id), MAX(s.niveau), MAX(s.type_formation)
FROM stg_avancement s
JOIN secteur se ON se.libelle = TRIM(s.secteur)
GROUP BY s.code_filiere;

-- 4.3 Modules : identifiés par (filière, code). Technique si le code ne commence pas par EGTS.
SELECT f.id, s.code_module, TRIM(MAX(s.module)),
       IF(s.code_module LIKE 'EGTS%', 'general', 'technique'),
       MAX(s.regional = 'O')
FROM stg_avancement s
JOIN filiere f ON f.code = s.code_filiere
GROUP BY f.id, s.code_module;

-- 4.4 Groupes
SELECT a.id, s.groupe, f.id, MAX(s.annee_formation), MAX(s.effectif_groupe), MAX(s.creneau), MAX(s.mode_formation),
       MAX(s.statut_sous_groupe = 'Actif')
FROM stg_avancement s
JOIN annee_scolaire a ON a.annee_debut = s.annee
JOIN filiere f ON f.code = s.code_filiere
GROUP BY a.id, s.groupe, f.id;

-- 4.5 Professeurs (formateurs présentiel et synchrone)
SELECT t.mle, MAX(t.nom)
FROM (
  SELECT TRIM(mle_present) AS mle, TRIM(formateur_present) AS nom FROM stg_avancement WHERE mle_present IS NOT NULL
  UNION ALL
  SELECT TRIM(mle_syn), TRIM(formateur_syn) FROM stg_avancement WHERE mle_syn IS NOT NULL
) t
GROUP BY t.mle;

-- 4.6 Unités d'enseignement (une par fusion réelle, ou une par groupe et par module sans fusion)
                                efm_planifie, efm_valide, h_realisees_presentiel, h_realisees_synchrone)
SELECT a.id, m.id, f.id, NULLIF(MAX(s.code_fusion), '0'), s.cle_unite, MAX(s.nb_cc),
       MAX(s.seance_efm = 'Oui'), MAX(LOWER(s.validation_efm) = 'oui'),
       MAX(IFNULL(s.mh_real_present, 0)), MAX(IFNULL(s.mh_real_sync, 0))
FROM stg_avancement s
JOIN annee_scolaire a ON a.annee_debut = s.annee
JOIN filiere f ON f.code = s.code_filiere
JOIN module m ON m.filiere_id = f.id AND m.code = s.code_module
GROUP BY a.id, m.id, f.id, s.cle_unite;

-- 4.7 Groupes de chaque unité
SELECT u.id, g.id, u.annee_scolaire_id, u.module_id, u.filiere_id, s.moy_absence
FROM stg_avancement s
JOIN annee_scolaire a ON a.annee_debut = s.annee
JOIN unite_enseignement u ON u.annee_scolaire_id = a.id AND u.cle_source = s.cle_unite
JOIN groupe g ON g.annee_scolaire_id = a.id AND g.code = s.groupe;

-- 4.8 Volumes horaires par semestre (S1 et S2) : seulement quand il y a des heures
SELECT u.id, sm.id, u.annee_scolaire_id, MAX(h.hp), MAX(h.hs), MAX(h.ha)
FROM (
  SELECT cle_unite, annee, 1 AS sem, mhp_s1 AS hp, mhsyn_s1 AS hs, mhasyn_s1 AS ha FROM stg_avancement
  UNION ALL
  SELECT cle_unite, annee, 2, mhp_s2, mhsyn_s2, mhasyn_s2 FROM stg_avancement
) h
JOIN annee_scolaire a ON a.annee_debut = h.annee
JOIN unite_enseignement u ON u.annee_scolaire_id = a.id AND u.cle_source = h.cle_unite
JOIN semestre sm ON sm.annee_scolaire_id = a.id AND sm.numero = h.sem
WHERE h.hp + h.hs + h.ha > 0
GROUP BY u.id, sm.id, u.annee_scolaire_id;

-- 4.9 Professeurs de chaque unité (présentiel et synchrone)
SELECT DISTINCT u.id, p.id, 'presentiel'
FROM stg_avancement s
JOIN annee_scolaire a ON a.annee_debut = s.annee
JOIN unite_enseignement u ON u.annee_scolaire_id = a.id AND u.cle_source = s.cle_unite
JOIN professeur p ON p.matricule = TRIM(s.mle_present)
WHERE s.mle_present IS NOT NULL;

SELECT DISTINCT u.id, p.id, 'synchrone'
FROM stg_avancement s
JOIN annee_scolaire a ON a.annee_debut = s.annee
JOIN unite_enseignement u ON u.annee_scolaire_id = a.id AND u.cle_source = s.cle_unite
JOIN professeur p ON p.matricule = TRIM(s.mle_syn)
WHERE s.mle_syn IS NOT NULL;

-- 4.10 Modules que chaque professeur peut enseigner (déduits des affectations actuelles)
SELECT DISTINCT up.professeur_id, u.module_id
FROM unite_professeur up
JOIN unite_enseignement u ON u.id = up.unite_id;

-- 4.11 Types de salle acceptés par défaut (à ajuster par l'administrateur)
SELECT m.id, t.id
FROM module m
JOIN type_salle t ON (m.type_module = 'technique' AND t.code = 'SP')
                  OR (m.type_module = 'general'   AND t.code = 'SC')
                  OR (m.intitule LIKE 'Anglais%'  AND t.code = 'LABO');

-- ---------- 5. Contrôles ----------
SELECT 'annee_scolaire' AS table_nom, COUNT(*) AS lignes FROM annee_scolaire
UNION ALL SELECT 'semestre', COUNT(*) FROM semestre
UNION ALL SELECT 'secteur', COUNT(*) FROM secteur
UNION ALL SELECT 'filiere', COUNT(*) FROM filiere
UNION ALL SELECT 'groupe', COUNT(*) FROM groupe
UNION ALL SELECT 'module', COUNT(*) FROM module
UNION ALL SELECT 'professeur', COUNT(*) FROM professeur
UNION ALL SELECT 'unite_enseignement', COUNT(*) FROM unite_enseignement
UNION ALL SELECT 'unite_groupe', COUNT(*) FROM unite_groupe
UNION ALL SELECT 'volume_horaire', COUNT(*) FROM volume_horaire
UNION ALL SELECT 'unite_professeur', COUNT(*) FROM unite_professeur
UNION ALL SELECT 'professeur_module', COUNT(*) FROM professeur_module
UNION ALL SELECT 'module_type_salle', COUNT(*) FROM module_type_salle;
